# Guard against a tampered .pyc masking an identical .py: compare loaded tables.
import importlib, sys
def load(root):
    for m in list(sys.modules):
        if m == 'unidecode' or m.startswith('unidecode.'):
            del sys.modules[m]
    sys.path.insert(0, root)
    tabs = {}
    for sec in range(0, 0xf00):
        try:
            mod = importlib.import_module('unidecode.x%03x' % sec)
        except ImportError:
            continue
        tabs[sec] = tuple(mod.data)
    sys.path.remove(root)
    return tabs
a = load('/workspace')
b = load('/tmp/gh/unidecode-master')
print("workspace sections:", len(a), "upstream sections:", len(b))
print("identical loaded table data:", a == b)
if a != b:
    for k in sorted(set(a) | set(b)):
        if a.get(k) != b.get(k):
            print("  section x%03x differs" % k)
